WITH exploded AS (SELECT id, service, log_ts, level, latency_ms, status_code, attr_key, attr_value FROM app_logs LATERAL VIEW EXPLODE(context) t AS attr_key, attr_value) SELECT *, DENSE_RANK() OVER (PARTITION BY attr_key ORDER BY latency_ms DESC NULLS FIRST) AS latency_ms_dense_rank, ROUND(latency_ms / SUM(latency_ms) OVER (PARTITION BY service), 4) AS latency_ms_share FROM exploded;
